export const sparklineTypeValues = ["line", "area", "bar"] as const;
export const sparklineColorValues = ["primary", "success", "danger", "muted"] as const;

/** A tiny line or bar graphic that shows the shape of a trend, without axes. Decoration unless it has a label. */
export interface SparklineSpecProps {
  /**
   * The values, oldest first. Non-numbers are ignored.
   */
  data: number[];
  /**
   * A line, a line with a soft area under it, or thin bars.
   * @default "line"
   */
  type?: "line" | "area" | "bar";
  /**
   * A text description, e.g. "Revenue, last 12 months: from 21K to 48K". Without it the graphic is hidden from assistive technology.
   */
  label?: string;
  /**
   * Width in pixels.
   * @default 96
   */
  width?: number;
  /**
   * Fills the width of its parent and keeps the aspect ratio of width and height. Use it for a wide chart in a KPI row.
   * @default false
   */
  responsive?: boolean;
  /**
   * Height in pixels.
   * @default 32
   */
  height?: number;
  /**
   * Color of the line or bars.
   * @default "primary"
   */
  color?: "primary" | "success" | "danger" | "muted";
  /**
   * Marks the last point of a line with a dot.
   * @default true
   */
  showLast?: boolean;
  /**
   * Mark the highest and lowest points with small rings, so the range shows without reading numbers.
   * @default false
   */
  showExtremes?: boolean;
  /**
   * Draw a dashed line at the average, to see which points sit above and below it.
   * @default false
   */
  showAverage?: boolean;
}

export const sparklineDefaults = {
  type: "line",
  width: 96,
  responsive: false,
  height: 32,
  color: "primary",
  showLast: true,
  showExtremes: false,
  showAverage: false,
} as const;

export const sparklineMeta = {
  "name": "Sparkline",
  "version": "0.1.0",
  "status": "experimental",
  "role": "img"
} as const;
